#!/usr/bin/env bash
# REQ-08 second-author review of the eight recipes by a fresh Sonnet session (owner choice 2026-11-15; a model, not a person: recorded as such).
# The session runs in /tmp/rl-review with copies of the recipe files only, writes /tmp/rl-review/review.md, and is told never to open any ground-truth file.
set -u -o pipefail
RL=/home/coder/workspaces/worktrees/IronClaude/eval-tasklist-review-panel/.dev/eval-workspaces/tasklist-review-panel/20261114-recipe-ledger
R=/tmp/rl-review; SLOT=/home/coder/workspaces/worktrees/IronClaude/eval-tasklist-review-panel/.dev/eval-workspaces/tasklist-review-panel/20261114-collab-process/with-slot.sh
PROMPT="You are the second author of eight review recipes (C1 to C8) of a document-review process. Your folder is $R. Read recipes/recipes.json, recipes/rl-block.txt, recipes/search-form.txt, recipes/README.md and neutral-table.txt there, and nothing else: do not open any other path outside $R, never open any file whose name contains ground-truth, and do not search the repository or home folder. For EACH recipe C1 to C8 do the swap test: replace every domain noun (file names, product names, feature names, specific wording that belongs to one document) by a neutral placeholder such as <ITEM>, <FILE>, <CLAIM>, read the recipe again, and decide (1) does it still read correctly and give a reviewer an executable procedure, (2) does it contain any issue-specific word, number, path or phrase that could only come from one known defect (list each such word verbatim), (3) is every step either a concrete action or a concrete question. Write $R/review.md with one section per recipe: verdict PASS or FAIL, the exact words that are issue-specific (or none), and the placeholder version of the first sentence of each step list. End with a table: Recipe | PASS/FAIL | issue-specific words. Do not edit any recipe file. Then reply with that table only."
S=$(date +%s)
( cd "$R" && bash "$SLOT" rl-review timeout 1800 claude -p --model claude-sonnet-5-5 --output-format json --no-session-persistence --permission-mode bypassPermissions <<<"$PROMPT" ) > "$RL/implement-report/recipe-review/session-${ROUND:-1}.json" 2> "$RL/implement-report/recipe-review/session-${ROUND:-1}.err"
echo "END review rc=$? wall=$(( $(date +%s)-S ))s review_md=$( [ -s $R/review.md ] && echo yes || echo no )"
